WITH flattened_attrs AS (SELECT id, plan, tier_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE plan = 'starter') SELECT id, lowest_price, avg_tier_price, COUNT(avg_tier_price) OVER (PARTITION BY plan ORDER BY entry_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_avg_tier_price, MAX(avg_tier_price) OVER (PARTITION BY plan ORDER BY entry_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_avg_tier_price, SUM(avg_tier_price) OVER (PARTITION BY plan ORDER BY entry_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_avg_tier_price FROM flattened_attrs
